// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 warpTs, uint256 rollBn) public {
        vm.assume(warpTs >= 1);
        vm.assume(rollBn >= 1);

        address payer = address(0xBEEF);
        uint256 amount = 10 ether;
        vm.deal(payer, amount);

        vm.warp(warpTs);
        vm.roll(bound(rollBn, 1, type(uint64).max));

        vm.prank(payer);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "call failed");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
